const enc = new TextEncoder(), dec = new TextDecoder();

/// plexus-proto's frame codec, running as wasm. One instance serves any
/// number of connections in a page: a read or a write is done before it
/// returns.
class Codec {
  /// What the last `read` found: the call, the seq as written (0 on a
  /// counted channel), and where the body lies in the bytes read.
  call = 0;
  seq = 0;
  start = 0;
  end = 0;
  /// Why the last `read` refused its bytes, for a person.
  error = "";
          x         ;
          at        ;
  /// The wasm's input buffer, kept while it is large enough.
          input = 0;
          room = 0;
          buf                         ;
          u8 = new Uint8Array(0);
          u32 = new Uint32Array(0);
          f64 = new Float64Array(0);

          constructor(x         ) {
    this.x = x;
    this.at = x.head();
  }

  /// Instantiate the codec from its wasm: the bytes, or a fetch of them.
  /// With neither, the wasm beside this module: fetched in a page or a
  /// worker, read from disk in Node.
  static async load(wasm                                              )                 {
    const w = await (wasm ?? beside());
    const made = w instanceof Response ? await WebAssembly.instantiateStreaming(w, {}) : await WebAssembly.instantiate(w, {});
    return new Codec(made.instance.exports                      );
