  body(bytes            )       {
    return this.start === this.end ? undefined : JSON.parse(dec.decode(bytes.subarray(this.start, this.end)));
  }

  /// One frame's bytes. `body` undefined is `null`; on a counted channel an
  /// item and an end with a `null` body take their short forms.
  write(call        , kind        , body       , seq = 0, numbered = false)             {
    const text = body === undefined ? "" : JSON.stringify(body), room = text.length * 3;
    const x = this.x, at = this.place(room);
    const { written } = enc.encodeInto(text, this.u8.subarray(at, at + room));
    const n = x.write(call, kind, seq, written, numbered ? 1 : 0);
    this.views();
    const out = x.output();
    return this.u8.slice(out, out + n);
  }

  /// The seq of the next frame of `call`, of `kind`, going way `side` (0
  /// caller to activation, 1 back), as both ends of an ordered channel count it.
  count(side       , call        , kind        )         {
    return this.x.count(side, call, kind);
  }

  /// Forget every call `count` has seen: a new connection.
  reset()       {
    this.x.reset();
  }
}

async function beside()                                   {
  const at = new URL("./plexus_proto_web.wasm", import.meta.url);
  if (at.protocol !== "file:") return fetch(at);
  const fs = "node:fs/promises";   // a name, so a page never resolves it
