/// Bytes out, bytes in. A WebSocket, a pipe, a worker's port, or `pair()`.

/// Who sent a frame that `tap` sees.

/// Two ends of a channel in one page. `tap` sees every frame that crosses.
function pair(tap      )                     {
  const on                                 = [() => {}, () => {}];
  const end = (me       )          => ({
    send(frame) {
      tap?.(me === 0 ? "caller" : "activation", frame);
      queueMicrotask(() => on[1 - me](frame));
    },
    receive(cb) { on[me] = cb; },
  });
  return [end(0), end(1)];
}

/// A call that failed. `payload` is the method's own error, typed by the
/// generated client; `code` names it.
class PlexusFailure              extends Error {
  code        ;
  payload   ;
  constructor(code        , message        , payload   ) {
    super(message || code);
    this.code = code;
    this.payload = payload;
  }
}

/// How many items a caller says it will take before it has taken any, and
/// how many it takes before saying so again.
const WINDOW = 256, TOP_UP = 128;

/// A failure as the wire carries it: `code` the case's name and `data` its
/// value. With `failure`, the payload is the method's own error, read back
/// from `{ code: data }`, or from `code` alone for a case with no value.
function failedFrom(f      , failure                           )                {
  const payload = failure ? failure(f.data === undefined ? f.code : { [f.code]: f.data }) : f.data;
  return new PlexusFailure(f.code, f.message ?? "", payload);
}

/// The caller's end: opens calls, hands their answers back.
class Connection {
  /// The hash the activation said at `hello`.
  interface                    ;
  /// Resolves at `hello`; rejects when the activation is not the interface
  /// this client was generated from, or the channel closes first.
           ready               ;
  /// Why the channel closed, once it has. Every call then fails with it.
  closed                    ;
