      const c = this.codec, kind = c.read(bytes);
      if (kind === Kind.hello) {
        this.interface = c.body(bytes).interface;
        if (expects && expects !== this.interface) refused(new Error(`the activation's interface is ${this.interface}; this client was generated from ${expects}`));
