    if (this.closed === undefined) this.channel.send(this.codec.write(id, kind, body));
  }

          open(method        , params      , sink      )         {
    const id = this.next++;
    if (this.closed !== undefined) {
      sink.fail({ code: "closed", message: this.closed });
      return id;
    }
    this.calls.set(id, sink);
    this.send(id, Kind.open, Object.keys(params).length ? [method, params] : [method]);
    return id;
  }

  /// One answer: the last item before the end. Called on a stream, it reads
  /// every item, granting credit as `stream` does. `failure` turns the
  /// method's own error, as the wire carries it, into its typed value.
  call(method        , params      , failure                           )                {
    return new Promise((resolve, reject) => {
      let got      , taken = 0, done = false;
      const id = this.open(method, params, {
        item: (b) => {
          got = b;
          // The open was credit for one. Unless the end follows at once, this
          // may be a stream: grant the rest of the window, as `stream` does.
          if (++taken === 1) queueMicrotask(() => { if (!done) this.send(id, Kind.credit, WINDOW - 1); });
          else if (taken % TOP_UP === 0) this.send(id, Kind.credit, TOP_UP);
        },
        end: () => { done = true; resolve(got); },
        fail: (f) => { done = true; reject(failedFrom(f, failure)); },
      });
    });
  }

  /// Many answers. Leaving the loop early sends `cancel`.
  stream(method        , params      , failure                           )                      {
    const self = this;
    return {
      [Symbol.asyncIterator]() {
        const ready         = [];
        let done = false, failed                   , wake                          ;
        const poke = () => { wake?.(); wake = undefined; };
        const id = self.open(method, params, {
          item: (b) => { ready.push(b); poke(); },
          end: () => { done = true; poke(); },
          fail: (f) => { failed = failedFrom(f, failure); done = true; poke(); },
        });
        self.send(id, Kind.credit, WINDOW - 1);   // the open itself carries credit for one
        let taken = 0;
        return {
          async next() {
            while (!ready.length && !done) await new Promise      ((ok) => { wake = ok; });
            if (ready.length) {
              // Every few items taken, say the activation may write that many more.
              if (++taken % TOP_UP === 0 && !done) self.send(id, Kind.credit, TOP_UP);
              return { value: ready.shift(), done: false };
            }
            if (failed) throw failed;
            return { value: undefined, done: true };
          },
          async return() {
            if (!done) { done = true; self.calls.delete(id); self.send(id, Kind.cancel); }
            return { value: undefined, done: true };
          },
        };
      },
    };
  }
}

/// The activation's end: reads `open`, runs the method, writes what it answers.
class Server {
          methods = new Map                 ();
  /// For each stream that is running: the items it may still write, and who is waiting to.
          streams = new Map                                                              ();
          channel         ;
          codec       ;

  constructor(channel         , codec       ) {
    this.channel = channel;
    this.codec = codec;
    channel.receive((bytes) => {
      const c = this.codec, kind = c.read(bytes);
      if (kind === Kind.open) {
        const [name, params] = c.body(bytes);
        return void this.run(c.call, name, params ?? {});
      }
      const s = this.streams.get(c.call);
      if (!s) return;
      if (kind === Kind.cancel) s.gone = true;
      else if (kind === Kind.credit) s.credit += c.body(bytes);
      else return;
      s.wake?.();
    });
    // Nobody is left to read: every stream stops at its next item.
    channel.closed?.(() => {
      for (const s of this.streams.values()) { s.gone = true; s.wake?.(); }
    });
  }

  /// Say which interface this is. The first frame of a connection.
  hello(hash        )       {
    this.channel.send(this.codec.write(0, Kind.hello, { interface: hash }));
  }

  method(name        , run                       , failure                             = (p) => p)       {
    this.methods.set(name, { stream: false, run, failure });
  }

  stream(name        , run                       , failure                             = (p) => p)       {
    this.methods.set(name, { stream: true, run, failure });
  }

  /// Say what is served at `at`: `<at>._ir` answers its IR and `<at>._hash`
  /// its hash, and `_tree` lists every place something is served.
